/// <summary>可识别的音频/视频扩展名（用于文件选择与拖放过滤）。</summary>
public static class AudioExts
{
    public static readonly IReadOnlySet<string> Set = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".3gp", ".aac", ".ac3", ".aif", ".aifc", ".aiff", ".alac", ".amr", ".ape", ".au", ".avi", ".caf", ".dff", ".dsf", ".dts", ".eac3", ".flac", ".flv", ".m2ts", ".m3u", ".m4a", ".m4b", ".mka", ".mkv", ".mov", ".mp1", ".mp2", ".mp3", ".mp4", ".mpc", ".oga", ".ogg", ".opus", ".snd", ".spx", ".ts", ".tta", ".voc", ".wav", ".wavpack", ".webm", ".wma", ".wv"
    };

    public static bool IsAudioLike(string? name)
    {
        if (string.IsNullOrEmpty(name)) return false;
        var ext = Path.GetExtension(name);
        return !string.IsNullOrEmpty(ext) && Set.Contains(ext);
    }
}
